/** The default lexicon: the course words (data/words.json, generated by the course package). */
import namesFile from './data/names.json' with { type: 'json' };
import wordsFile from './data/words.json' with { type: 'json' };
import { JaLexicon, type NameEntry, type WordEntry } from './lexicon.ts';

export const COURSE_WORDS = wordsFile as WordEntry[];

let shared: JaLexicon | undefined;

/** The lexicon of the course words (built once), or a new one that also knows `names`. */
export function courseLexicon(names?: readonly NameEntry[]): JaLexicon {
  if (names && names.length > 0) return new JaLexicon(COURSE_WORDS, { names });
  shared ??= new JaLexicon(COURSE_WORDS);
  return shared;
}

/** Proper nouns of the course (generated from packages/course data/names.json). */
export const COURSE_NAMES = namesFile as NameEntry[];

let grading: JaLexicon | undefined;

/** The lexicon used to grade answers: course words and course names. */
export function graderLexicon(): JaLexicon {
  grading ??= new JaLexicon(COURSE_WORDS, { names: COURSE_NAMES });
  return grading;
}
